cat > src/statement.mjs <<'EOF'
/**
 * The monthly usage statement as plain text, at most 72 characters wide.
 * Amounts are whole cents; all arithmetic stays in integers.
 * @param {{ customer: string, account: string, period: string, currency: string,
 *           lines: { service: string, quantity: number, unit: string, amount_cents: number }[],
 *           credits: { reason: string, amount_cents: number }[] }} data
 * @returns {string}
 */

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

const WIDTH = 72;

function groups(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function money(cents) {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  return `${sign}$${groups(Math.floor(abs / 100))}.${String(abs % 100).padStart(2, "0")}`;
}

function monthName(period) {
  const m = /^(\d{4})-(\d{2})$/.exec(period);
  if (!m || Number(m[2]) < 1 || Number(m[2]) > 12) return period;
  return `${MONTHS[Number(m[2]) - 1]} ${m[1]}`;
}

function wrap(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  const rows = [];
  let cur = "";
  for (const w of words) {
    if (cur && cur.length + 1 + w.length > width) {
      rows.push(cur);
      cur = w;
    } else {
      cur = cur ? `${cur} ${w}` : w;
    }
  }
  if (cur) rows.push(cur);
  return rows;
}

export function renderStatement(data) {
  const out = [];
  const rule = "-".repeat(WIDTH);

  const title = `Usage statement, ${monthName(data.period)}`;
  out.push(title);
  out.push(data.customer);
  out.push(`Account ${data.account}`);
  out.push(`Amounts in ${data.currency}`);
  out.push("");

  const qtyW = Math.max(3, ...data.lines.map((l) => groups(l.quantity).length));
  const unitW = Math.max(4, ...data.lines.map((l) => l.unit.length));
  const amtW = Math.max(
    6,
    ...data.lines.map((l) => money(l.amount_cents).length),
    ...data.credits.map((c) => money(c.amount_cents).length),
  );
  const charges = data.lines.reduce((s, l) => s + l.amount_cents, 0);
  const credits = data.credits.reduce((s, c) => s + c.amount_cents, 0);
  const total = charges + credits;
  const totalStr = money(total);
  const amtCol = Math.max(amtW, totalStr.length, money(charges).length);
  const svcW = WIDTH - qtyW - unitW - amtCol - 6;

  const row = (svc, qty, unit, amt) =>
    `${svc.padEnd(svcW)}  ${qty.padStart(qtyW)}  ${unit.padEnd(unitW)}  ${amt.padStart(amtCol)}`.replace(/\s+$/, "");
  const pair = (label, amt) => {
    const gap = WIDTH - Math.min(WIDTH, label.length) - amtCol;
    return `${label}${" ".repeat(Math.max(2, gap))}${amt.padStart(amtCol)}`;
  };

  out.push(row("Service", "Qty", "Unit", "Amount").replace("Qty", "Qty".padStart(qtyW)));
  out.push(rule);
  for (const l of data.lines) {
    out.push(row(l.service, groups(l.quantity), l.unit, money(l.amount_cents)));
  }
  out.push(rule);
  out.push(pair("Charges", money(charges)));
  out.push("");
  out.push("Credits");
  for (const c of data.credits) {
    const labelW = WIDTH - amtCol - 2;
    const parts = wrap(c.reason, labelW - 2);
    parts.forEach((p, i) => {
      const label = `  ${p}`;
      out.push(i === parts.length - 1 ? pair(label, money(c.amount_cents)) : label);
    });
  }
  out.push(pair("Total credits", money(credits)));
  out.push("");
  out.push("=".repeat(WIDTH));
  out.push(pair(`TOTAL DUE (${data.currency})`, totalStr));
  out.push("=".repeat(WIDTH));

  return `${out.join("\n")}\n`;
}
EOF
